import { BaseException } from '../../base-exception';
import { Locale } from '../../locale';

export class DuplicateSessionException extends BaseException {
    constructor() {
        super('Game.DuplicateSession', 'User connected on a different device');
    }

    public localise(locale: Locale) {
        this.buttonText = this.getButtonText(locale);

        switch (locale) {
            case 'it-it':
                this.displayMessage = 'Sei collegato al gioco da due dispositivi, per favore chiudine uno per continuare a giocare';
                break;
            case 'es-es':
                this.displayMessage = '¡Vaya! Tu cuenta ya está abierta en otro dispositivo.';
                break;
            default:
                this.displayMessage = 'Oops! It looks like you\'re already logged in on a different device.';
                break;
        }
    }
}
